colors = {'pink': 6, 'red': 7, 'purple': 8}
pegs = {'lightest': [0.5365688800811768, 0.1327185034751892], 'middle': [0.45625001192092896, 0.22187499701976776], 'darkest': [0.37593114376068115, 0.3110314905643463]}
off = 0.018

def peg_of(pos):
    best = None; bd = 1e9
    for k, p in pegs.items():
        d = (pos[0]-p[0])**2 + (pos[1]-p[1])**2
        if d < bd:
            bd = d; best = k
    return best

def parse_goal(goal):
    src = None
    for c, oid in colors.items():
        if c in goal:
            src = oid
    if 'middle' in goal:
        tgt = 'middle'
    elif 'dark' in goal:
        tgt = 'darkest'
    else:
        tgt = 'lightest'
    return src, tgt

for step in range(5):
    g = primitives.call(name='get_cliport_task_language_goal')
    goal = g.output.get('language_goal') if g.ok else None
    print('goal:', goal)
    if not goal:
        break
    src, tgt = parse_goal(goal)
    r = primitives.call(name='inspect_cliport_instances', prompt='disks')
    poses = {}
    for inst in r.output.get('instances', []):
        poses[inst['object_id']] = inst['pose0'][0]
    if src is None or src not in poses:
        print('cannot parse', goal); break
    sp = poses[src]
    if peg_of(sp) == tgt:
        print('already satisfied'); break
    n_on_tgt = 0
    for oid in (6, 7, 8):
        if oid != src and peg_of(poses[oid]) == tgt:
            n_on_tgt += 1
    pick_pose = [[sp[0] + off, sp[1], sp[2] + 0.012], [0.0, 0.0, 0.0, 1.0]]
    tp = pegs[tgt]
    place_pose = [[tp[0] + off, tp[1], 0.045 + 0.013 * n_on_tgt], [0.0, 0.0, 0.0, 1.0]]
    rs = primitives.call(name='inspect_cliport_instance', object_id=src, prompt=goal)
    ev = rs.output.get('evidence_id')
    primitives.call(name='record_cliport_evidence', key='step_%d' % step, value={'goal': goal, 'source': src, 'target': tgt, 'pick': pick_pose, 'place': place_pose})
    a = primitives.call(name='submit_cliport_pick_place_action', evidence_ids=[ev, 'cliport:instance:5:1'], pick_pose=pick_pose, place_pose=place_pose, source_object_id=src, target_object_id=5, prompt=goal)
    print('action ok', a.ok, a.output.get('stepped') if a.ok else str(a.output)[:300])
    if not a.ok:
        break
    r2 = primitives.call(name='inspect_cliport_instance', object_id=src)
    np_ = r2.output['instance']['pose0'][0]
    print('src now', [round(v,3) for v in np_], peg_of(np_))
    if peg_of(np_) != tgt:
        print('move failed'); break
